x/frontend-app-profile/git/commits/1a9149d07f4971a115938d2c020f96340b0c91c5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/759355?v=4","events_url":"https://api.github.com/users/arbrandes/events{/privacy}","followers_url":"https://api.github.com/users/arbrandes/followers","following_url":"https://api.github.com/users/arbrandes/following{/other_user}","gists_url":"https://api.github.com/users/arbrandes/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/arbrandes","id":759355,"login":"arbrandes","node_id":"MDQ6VXNlcjc1OTM1NQ==","organizations_url":"https://api.github.com/users/arbrandes/orgs","received_events_url":"https://api.github.com/users/arbrandes/received_events","repos_url":"https://api.github.com/users/arbrandes/repos","site_admin":false,"starred_url":"https://api.github.com/users/arbrandes/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/arbrandes/subscriptions","type":"User","url":"https://api.github.com/users/arbrandes","user_view_type":"public"},"html_url":"https://github.com/openedx/frontend-app-profile/commit/1a9149d07f4971a115938d2c020f96340b0c91c5","node_id":"C_kwDOCddS_toAKDFhOTE0OWQwN2Y0OTcxYTExNTkzOGQyYzAyMGY5NjM0MGIwYzkxYzU","parents":[{"html_url":"https://github.com/openedx/frontend-app-profile/commit/487b2a66ea84b9f8674bd1f66b445182036496ad","sha":"487b2a66ea84b9f8674bd1f66b445182036496ad","url":"https://api.github.com/repos/openedx/frontend-app-profile/commits/487b2a66ea84b9f8674bd1f66b445182036496ad"}],"sha":"1a9149d07f4971a115938d2c020f96340b0c91c5","url":"https://api.github.com/repos/openedx/frontend-app-profile/commits/1a9149d07f4971a115938d2c020f96340b0c91c5"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/759355?v=4","events_url":"https://api.github.com/users/arbrandes/events{/privacy}","followers_url":"https://api.github.com/users/arbrandes/followers","foll